 out=dict(coach=car,people=people,opaque_U_W_m2K=U,inside_equipment_W=insideW,glass_m2=glass,opaque_m2=opaque,UA_W_K=ua,fresh_air_m3_s=oa,door_average_m3_s=t['average_door_leakage_m3_s'],hot_evening_dry_kW=(sensible+pl)*factor,hot_day_dry_kW=(sensible+pl+solar)*factor,hot_day_humid_kW=(sensible+pl+solar+latent)*factor,hot_day_sensible_kW=(sensible+solar)*factor,components_before_allowance_kW=dict(conduction=cond,ventilation_and_door_sensible=vent,people_sensible=ps,people_latent=pl,inside_equipment=inside,solar_increment=solar,humidity_ratio_stress_increment=latent))
